-  // permissions by a parent frame.
+navigator.vr.requestDevice().then((device) => {
+  vrDevice = device;
+  onVRAvailable();
+}, (err) => {
+  // Could not find any available VR hardware or an error occurred querying VR
+  // hardware.
 });
 ```

